const labelMap = {
  normal: '正常考勤',
  late: '迟到',
  absent: '缺勤',
  leave: '请假',
  goout: '外出报备'
};
const rows = (ctx.data && ctx.data.objects) || [];
const data = rows.map(function (r) {
  return { name: labelMap[r.status] || r.status, value: Number(r.attCount) || 0 };
});
return {
  tooltip: { trigger: 'item' },
  legend: { bottom: 0 },
  series: [
    { type: 'pie', radius: '62%', name: '考勤状态分布', data: data, label: { formatter: '{b}: {c}' } }
  ]
};
